from aerelith.core.result import Result

def top_by_weight(rows, *, k):
    """Return the k rows with highest weight, sorted descending.

    Args:
        rows: List of dicts with 'id' and 'weight'.
        k: Number of top rows to return (1 <= k <= len(rows)).

    Returns:
        Result containing the sorted list of dicts, or an error code.
    """
    if not rows:
        return Result(ok=False, value=None, err="E_EMPTY")

    if k < 1 or k > len(rows):
        return Result(ok=False, value=None, err="E_RANGE")

    # Sort by weight descending, then by id ascending for stability
    sorted_rows = sorted(rows, key=lambda r: (-r['weight'], r['id']))
    return Result(ok=True, value=sorted_rows[:k], err=None)
