def merge_quota(a, b):
    if not a and not b:
        return Result(ok=False, value=None, err='E_EMPTY')

    merged = {}
    all_tenants = set(a.keys()) | set(b.keys())

    for tenant in all_tenants:
        val_a = a.get(tenant)
        val_b = b.get(tenant)

        if val_a is not None and val_b is not None:
            if val_a != val_b:
                return Result(ok=False, value=None, err='E_CONFLICT')
            merged[tenant] = val_a
        else:
            merged[tenant] = val_a if val_a is not None else val_b

    return Result(ok=True, value=merged, err=None)

